# Generated by Descant: acceptance tests.

require "rails_helper"
require "json"

RSpec.describe Timekeeping::Handoff::Checkpoint do
  def tenant_lens_entry_row(id:, company_id:, duration:)
    {
      "id" => id, "company_id" => company_id, "version" => 2, "project_id" => 1, "user_id" => 1,
      "agent_id" => nil, "work_date" => Date.new(2026, 10, 1), "duration" => duration, "note" => "",
      "bill_status" => "unbilled", "review_status" => "not_required", "locked" => false,
      "source" => "manual", "source_metadata" => {}, "external_run_id" => nil,
      "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {}, "discarded_at" => nil,
      "created_at" => Time.utc(2026, 10, 1, 12), "updated_at" => Time.utc(2026, 10, 1, 12)
    }
  end

  def tenant_lens_tables(entries)
    {
      "entries" => entries, "reservations" => [], "invoice_operations" => [],
      "entry_audits" => [], "idempotency_records" => []
    }
  end

  it "changes the digest only for the company whose entry changed" do
    company_b_entry = tenant_lens_entry_row(id: 2, company_id: 200, duration: 30.0)
    original = described_class.build(
      tables: tenant_lens_tables([tenant_lens_entry_row(id: 1, company_id: 100, duration: 0.1 + 0.2), company_b_entry])
    )
    # "A changed field, or a float differing in its last bit, fails `verify` for that table and company only."
    changed = described_class.build(
      tables: tenant_lens_tables([tenant_lens_entry_row(id: 1, company_id: 100, duration: (0.1 + 0.2).next_float), company_b_entry])
    )

    expect(original.digest["entries"].keys).to contain_exactly(100, 200)
    expect(original.digest["entries"][100][:count]).to eq(1)
    expect(original.digest["entries"][200][:count]).to eq(1)
    expect(changed.digest["entries"][100][:checksum]).not_to eq(original.digest["entries"][100][:checksum])
    expect(changed.digest["entries"][200]).to eq(original.digest["entries"][200])
  end
end

RSpec.describe Timekeeping::Handoff::Checkpoint do
  it "refuses an audit row without a company_id and names the table" do
    audit_without_company = {
      "id" => 1, "company_id" => nil, "entry_id" => 1, "actor_type" => "User", "actor_id" => 5,
      "action" => "create", "before" => nil, "after" => { "duration" => 60.0 },
      "entry_created_at" => Time.utc(2026, 10, 1, 12), "created_at" => Time.utc(2026, 10, 1, 12)
    }
    tables = {
      "entries" => [], "reservations" => [], "invoice_operations" => [],
      "entry_audits" => [audit_without_company], "idempotency_records" => []
    }

    # "Every row carries its `company_id`." A row with no company could never be checked per company.
    expect { described_class.build(tables: tables) }
      .to raise_error(Timekeeping::Handoff::Checkpoint::ShapeError, /entry_audits/)
  end
end

RSpec.describe Timekeeping::Handoff::Checkpoint do
  it "verify reports a changed entry note only for that table and company" do
    checkpoint_class = Timekeeping::Handoff::Checkpoint
    at = Time.utc(2026, 1, 2, 3, 4, 5.123456r)
    entry = lambda do |id, company_id, note|
      values = {
        "id" => id, "company_id" => company_id, "version" => 2, "project_id" => 7, "user_id" => 8,
        "agent_id" => nil, "work_date" => Date.new(2026, 1, 2), "duration" => 0.1 + 0.2, "note" => note,
        "bill_status" => "unbilled", "review_status" => "not_required", "locked" => false,
        "source" => "manual", "source_metadata" => {}, "external_run_id" => nil,
        "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
        "discarded_at" => nil, "created_at" => at, "updated_at" => at
      }
      checkpoint_class::TABLES.fetch("entries").index_with { |column| values.fetch(column) }
    end
    audit = lambda do |id, company_id, entry_id|
      values = {
        "id" => id, "company_id" => company_id, "entry_id" => entry_id, "actor_type" => "User",
        "actor_id" => 8, "actor_name" => nil, "action" => "create", "before" => nil, "after" => { "note" => "a" },
        "entry_created_at" => at, "created_at" => at
      }
      checkpoint_class::TABLES.fetch("entry_audits").index_with { |column| values.fetch(column) }
    end
    tables_with = lambda do |company_one_note|
      tables = checkpoint_class::TABLES.keys.index_with { [] }
      tables["entries"] = [entry.call(1, 1, company_one_note), entry.call(2, 2, "same")]
      tables["entry_audits"] = [audit.call(1, 1, 1), audit.call(2, 2, 2)]
      tables
    end

    original = JSON.parse(checkpoint_class.build(tables: tables_with.call("before")).to_json)
    changed = JSON.parse(checkpoint_class.build(tables: tables_with.call("after")).to_json)
    digest_key = original.keys.find { |key| key.match?(/digest|manifest|checksum/) }
    expect(digest_key).not_to be_nil
    # Rows from the changed checkpoint, digest from the original one.
    tampered = checkpoint_class.from_json(JSON.generate(changed.merge(digest_key => original.fetch(digest_key))))

    mismatches = checkpoint_class.verify(tampered).map { |m| [m.fetch(:table).to_s, m.fetch(:company_id)] }

    # "A changed field, or a float differing in its last bit, fails `verify` for that table and company only."
    expect(mismatches).to eq([["entries", 1]])
  end
end

RSpec.describe Timekeeping::Handoff::Checkpoint do
  it "verify reports a duration one bit apart only for that table and company" do
    checkpoint_class = Timekeeping::Handoff::Checkpoint
    at = Time.utc(2026, 1, 2, 3, 4, 5.123456r)
    entry = lambda do |id, company_id, duration|
      values = {
        "id" => id, "company_id" => company_id, "version" => 3, "project_id" => 7, "user_id" => 8,
        "agent_id" => nil, "work_date" => Date.new(2026, 1, 2), "duration" => duration, "note" => "",
        "bill_status" => "unbilled", "review_status" => "not_required", "locked" => false,
        "source" => "manual", "source_metadata" => {}, "external_run_id" => nil,
        "external_session_id" => nil, "proof_url" => nil, "proof_metadata" => {},
        "discarded_at" => nil, "created_at" => at, "updated_at" => at
      }
      checkpoint_class::TABLES.fetch("entries").index_with { |column| values.fetch(column) }
    end
    audit = lambda do |id, company_id, entry_id|
      values = {
        "id" => id, "company_id" => company_id, "entry_id" => entry_id, "actor_type" => "User",
        "actor_id" => 8, "actor_name" => nil, "action" => "create", "before" => nil, "after" => { "note" => "" },
        "entry_created_at" => at, "created_at" => at
      }
      checkpoint_class::TABLES.fetch("entry_audits").index_with { |column| values.fetch(column) }
    end
    base_duration = 0.1 + 0.2
    tables_with = lambda do |company_one_duration|
      tables = checkpoint_class::TABLES.keys.index_with { [] }
      tables["entries"] = [entry.call(1, 1, company_one_duration), entry.call(2, 2, base_duration)]
      tables["entry_audits"] = [audit.call(1, 1, 1), audit.call(2, 2, 2)]
      tables
    end

    original = JSON.parse(checkpoint_class.build(tables: tables_with.call(base_duration)).to_json)
    changed = JSON.parse(checkpoint_class.build(tables: tables_with.call(base_duration.next_float)).to_json)
    digest_key = original.keys.find { |key| key.match?(/digest|manifest|checksum/) }
    expect(digest_key).not_to be_nil
    # Rows from the checkpoint with the next float, digest from the original one.
    tampered = checkpoint_class.from_json(JSON.generate(changed.merge(digest_key => original.fetch(digest_key))))

    mismatches = checkpoint_class.verify(tampered).map { |m| [m.fetch(:table).to_s, m.fetch(:company_id)] }

    # "The checksum must tell float values apart bit for bit."
    # "A changed field, or a float differing in its last bit, fails `verify` for that table and company only."
    expect(mismatches).to eq([["entries", 1]])
    expect(checkpoint_class.verify(checkpoint_class.from_json(JSON.generate(original)))).to eq([])
  end
end
